function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  validation: ValidationResult,
  config?: {history?: {enabled: boolean}}
): void {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') {
    void handleListSessions(ws, session, sessionStore, message.limit, message.before, config);
  }
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  limit: number | undefined,
  before: SessionCursor | undefined,
  config?: {history?: {enabled: boolean}}
): Promise<void> {
  if (!config?.history?.enabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled');
    return;
  }

  if (!sessionStore.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Store does not support listing conversations');
    return;
  }

  try {
    const sessions = await sessionStore.listFor(session.userId, {limit, before});
    sendSessionList(ws, sessions);
  } catch (error) {
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, error.message);
      return;
    }
    const message = error instanceof Error ? error.message : 'Unknown error';
    log.error('message', 'failed to list conversations', {userId: session.userId, error: message});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
  }
}

